// PITFALL: Signed/Unsigned Implicit Conversion

int s_count = -1;
size_t u_limit = 10;

// PITFALL 1: Comparison results in unintended behavior
// s_count (-1) converts to size_t (MAX_SIZE)
if (s_count > u_limit) { /* Always true */ }

// PITFALL 2: Arithmetic wrap-around
// Result is MAX_SIZE + 9, not 9
size_t wrapped_result = s_count + u_limit;

// FIX 1: Explicit cast to common signed type (if safe)
// Requires u_limit to fit in int.
int fixed_result_A = s_count + static_cast<int>(u_limit);

// FIX 2: Standard practice - use a safe signed type (e.g., long long)
// Cast BOTH to the common signed type for calculation
using SafeType = long long;
SafeType safe_s = static_cast<SafeType>(s_count);
SafeType safe_u = static_cast<SafeType>(u_limit);

SafeType fixed_result_B = safe_s + safe_u;
